using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    // Default type resolver so common types are available
    TypeInfoResolver = JsonSerializerOptions.Default.TypeInfoResolver
};

// 1) Strongly-typed retrieval: JsonTypeInfo<T> via the generic overload
JsonTypeInfo<int[]> arrayInfo = (JsonTypeInfo<int[]>)options.GetTypeInfo(typeof(int[]));
Console.WriteLine($"Got typed metadata for: {arrayInfo.Type.Name}");

// 2) Probe without throwing using TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringInfo))
{
    Console.WriteLine($"Metadata available for: {stringInfo.Type.Name}");
}
else
{
    Console.WriteLine("Metadata NOT available for String");
}

// Probe for a type that has no resolver (simulate by using an empty resolver)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty — resolves nothing
};

if (limited.TryGetTypeInfo(typeof(string), out _))
{
    Console.WriteLine("Unexpectedly found metadata");
}
else
{
    Console.WriteLine("No metadata for String (no resolver) — no exception thrown!");
}

